-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per client (customer) of the company. Needs client.view.
CREATE VIEW rpt.Client
AS
SELECT
    c.Id AS ClientId,
    c.ClientCode AS ClientCode,
    c.Name AS ClientName,
    ct.Name AS ClientType,
    cs.Name AS ClientStatus,
    cs.SystemCode AS ClientStatusCode,
    ind.Name AS Industry,
    am.DisplayName AS AccountManager,
    c.IsSample AS IsSample,
    CAST(c.CreatedAt AS DATE) AS CreatedDate
FROM crm.Client AS c
JOIN lkp.ClientType AS ct ON ct.TenantId = c.TenantId AND ct.Id = c.ClientTypeId
JOIN lkp.ClientStatus AS cs ON cs.TenantId = c.TenantId AND cs.Id = c.ClientStatusId
LEFT JOIN lkp.Industry AS ind ON ind.TenantId = c.TenantId AND ind.Id = c.IndustryId
LEFT JOIN sec.AppUser AS am ON am.TenantId = c.TenantId AND am.Id = c.AccountManagerUserId
WHERE c.DeletedAt IS NULL AND EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(c.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'client.view'));
GO
EXEC sys.sp_addextendedproperty @name = N'MS_Description', @value = N'One row per client (customer) of the company. Needs client.view.',
    @level0type = N'SCHEMA', @level0name = N'rpt', @level1type = N'VIEW', @level1name = N'Client';
GO
